      alt: "A modern house surrounded by desert landscape at sunset",
      size: "4.8 MB",
      type: "JPEG",
      added: "May 2026",
      owner: "Brand Studio"
    };

    const Button = ({ className = "", children, id, type = "button", ariaControls }) => `
      <button
        ${id ? `id="${id}"` : ""}
        type="${type}"
        class="button ${className}"
        ${ariaControls ? `aria-controls="${ariaControls}"` : ""}
      >
        ${children}
      </button>
    `;

    const Header = () => `
      <header class="topbar">
        <div class="brand" aria-label="Pixel Library">
          <span class="brand-mark" aria-hidden="true">P</span>
          <span>Pixel Library</span>
        </div>
        <a class="library-link" href="#" aria-label="Back to library">Back to library</a>
      </header>
    `;

    const Metadata = ({ label, value }) => `
      <div class="meta-item">
        <span class="meta-label">${label}</span>
        <span class="meta-value">${value}</span>
      </div>
    `;

    const ImagePreview = ({ item }) => `
      <main class="preview-card">
        <section class="image-frame" aria-label="Image preview">
          <img src="${item.source}" alt="${item.alt}">
        </section>
