              ${Metadata({ label: "File size", value: item.size })}
              ${Metadata({ label: "Added", value: item.added })}
              ${Metadata({ label: "Owner", value: item.owner })}
            </div>
          </div>
          <div class="actions">
            ${Button({ className: "button-secondary", children: "Download" })}
            ${Button({
              id: "delete-trigger",
              className: "button-danger trigger",
              children: "Delete image",
              ariaControls: "delete-dialog"
            })}
          </div>
        </aside>
      </main>
    `;

    const DeleteDialog = ({ item }) => `
      <div id="delete-dialog" class="modal-root" role="presentation" aria-hidden="true">
        <div class="modal-backdrop" data-close-modal></div>
        <section
          class="modal-card"
          role="dialog"
          aria-modal="true"
          aria-labelledby="dialog-title"
          aria-describedby="dialog-description"
        >
          <div class="modal-icon" aria-hidden="true">!</div>
          <h2 id="dialog-title">Delete this image?</h2>
          <p id="dialog-description">
            This will permanently remove "${item.title}" from your library. This action cannot be undone.
          </p>
          <div class="modal-actions">
            ${Button({ className: "button-secondary", children: "Cancel", id: "cancel-delete" })}
            ${Button({ className: "button-danger", children: "Yes, delete it", id: "confirm-delete" })}
          </div>
        </section>
      </div>
    `;

    const App = ({ item }) => `
      <div class="app-shell">
        ${Header()}
        ${ImagePreview({ item })}
      </div>
      ${DeleteDialog({ item })}
    `;

    document.getElementById("app").innerHTML = App({ item: image });

    const modal = document.getElementById("delete-dialog");
    const trigger = document.querySelector(".trigger");
    const cancelButton = document.getElementById("cancel-delete");
    const confirmButton = document.getElementById("confirm-delete");
    const closeTargets = document.querySelectorAll("[data-close-modal]");
    let previouslyFocusedElement = null;

    const openDialog = () => {
      previouslyFocusedElement = document.activeElement;
      modal.classList.add("is-open");
      modal.setAttribute("aria-hidden", "false");
